html,body{margin:0;height:100%;background:#0f172a;font-family:'Open Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#e2e8f0;}
*{box-sizing:border-box;}
.wrap{height:calc(var(--appsmith-ui-height)*1px);overflow:auto;padding:18px 22px;}
.filter{margin-bottom:18px;}
.filter label{display:block;font-size:13px;color:#60a5fa;font-weight:600;margin-bottom:6px;}
.filter select{background:#1e293b;color:#fff;border:1px solid #334155;border-radius:6px;padding:8px 12px;font-size:14px;min-width:220px;outline:none;cursor:pointer;}
.filter select:focus{border-color:#3b82f6;}
.tblwrap{border:1px solid #1e293b;border-radius:8px;overflow:auto;}
table{width:100%;border-collapse:collapse;font-size:14px;}
thead th{position:sticky;top:0;background:#0f172a;color:#cbd5e1;font-weight:700;text-align:left;padding:13px 18px;white-space:nowrap;border-bottom:2px solid #1e293b;}
thead th.r{text-align:right;}
tbody td{padding:12px 18px;color:#e2e8f0;white-space:nowrap;} tbody td.r{text-align:right;}
tbody tr:nth-child(odd){background:#1e293b;}
.empty{padding:44px 20px;text-align:center;color:#94a3b8;}
.empty .big{font-size:15px;color:#cbd5e1;margin-bottom:6px;}
.empty .sm{font-size:13px;color:#64748b;}
::-webkit-scrollbar{width:10px;background:#0f172a;} ::-webkit-scrollbar-thumb{background:#1e293b;border-radius:4px;border:2px solid #0f172a;}

