function esc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
var selAttr="ALL";
function render(){
  var m=appsmith.model||{}; var all=m.rows||[];
  var aset={}; all.forEach(function(r){ if(r.Attribute) aset[r.Attribute]=true; });
  var attrs=Object.keys(aset).sort();
  if(selAttr!=="ALL" && attrs.indexOf(selAttr)<0) selAttr="ALL";
  var rows=all.filter(function(r){ return selAttr==="ALL" || r.Attribute===selAttr; });
  rows.sort(function(a,b){ var c=String(a.Attribute||"").localeCompare(String(b.Attribute||"")); return c!==0?c:String(b._sort||"").localeCompare(String(a._sort||"")); });

  var opts='<option value="ALL"'+(selAttr==="ALL"?" selected":"")+'>All Attributes</option>'
    + attrs.map(function(a){ return '<option value="'+esc(a)+'"'+(selAttr===a?" selected":"")+'>'+esc(a)+'</option>'; }).join('');
  var html='<div class="filter"><label>Attribute</label><select id="attrSel">'+opts+'</select></div>';

  if(m.isLoading){ html+='<div class="empty"><div class="big">Loading…</div></div>'; }
  else if(!all.length){
    html+='<div class="empty"><div class="big">The Location needs to have Attributes in order to allow for Production Data values to be entered.</div><div class="sm">No monthly attribute data for this location.</div></div>';
  } else if(!rows.length){
    html+='<div class="empty"><div class="big">No data for the selected attribute.</div></div>';
  } else {
    html+='<div class="tblwrap"><table><thead><tr><th>Attribute</th><th>Month</th><th class="r">Value</th></tr></thead><tbody>';
    rows.forEach(function(r){
      html+='<tr><td>'+esc(r.Attribute)+'</td><td>'+esc(r.Month)+'</td><td class="r">'+esc(r.Value)+'</td></tr>';
    });
    html+='</tbody></table></div>';
  }
  var root=document.getElementById("root"); if(!root) return;
  root.innerHTML='<div class="wrap">'+html+'</div>';
  var sel=document.getElementById("attrSel");
  if(sel) sel.onchange=function(e){ selAttr=e.target.value; render(); };
}
appsmith.onReady(function(){ render(); appsmith.onModelChange(render); });

